--
-- Table structure for table `berths`
--

DROP TABLE IF EXISTS `berths`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `berths` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `berth_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '泊位编号',
  `port_area_id` bigint DEFAULT NULL COMMENT '所属港区ID',
  `wharf_id` bigint DEFAULT NULL COMMENT '所属码头ID',
  `port_area` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '港区名称',
  `berth_type` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '泊位类别',
  `berth_name` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '泊位名称',
  `wharf_direction` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '码头方向',
  `longitude` decimal(10,6) DEFAULT NULL COMMENT '经度',
  `latitude` decimal(10,6) DEFAULT NULL COMMENT '纬度',
  `start_latitude` decimal(10,6) DEFAULT NULL COMMENT '起始纬度',
  `start_longitude` decimal(10,6) DEFAULT NULL COMMENT '起始经度',
  `end_latitude` decimal(10,6) DEFAULT NULL COMMENT '终止纬度',
  `end_longitude` decimal(10,6) DEFAULT NULL COMMENT '终止经度',
  `berth_direction` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '泊位方向',
  `max_draft` decimal(6,2) DEFAULT NULL COMMENT '最大吃水',
  `berth_length` decimal(8,2) DEFAULT NULL COMMENT '泊位长度',
  `berth_depth` decimal(6,2) DEFAULT NULL COMMENT '泊位水深',
  `berth_status` enum('FREE','OCCUPIED','MAINTENANCE') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT 'FREE' COMMENT '泊位状态',
  `contact_phone` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '联系电话',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `berth_code` (`berth_code`) USING BTREE,
  KEY `port_area_id` (`port_area_id`) USING BTREE,
  KEY `wharf_id` (`wharf_id`) USING BTREE,
  CONSTRAINT `berths_ibfk_port_area` FOREIGN KEY (`port_area_id`) REFERENCES `port_areas` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `berths_ibfk_wharf` FOREIGN KEY (`wharf_id`) REFERENCES `wharves` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='港口泊位数据表';
/*!40101 SET character_set_client = @saved_cs_client */;

