--
-- Table structure for table `billing_vouchers`
--

DROP TABLE IF EXISTS `billing_vouchers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `billing_vouchers` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `voucher_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '计费凭证编号',
  `fiscal_year` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '会计年度编号',
  `fiscal_period` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '会计期间编号',
  `certificate_id` bigint NOT NULL COMMENT '签证单ID',
  `voyage_id` bigint DEFAULT NULL COMMENT '航次ID',
  `vessel_id` bigint DEFAULT NULL COMMENT '船舶ID',
  `agent_id` bigint DEFAULT NULL COMMENT '船代ID',
  `start_berth_id` bigint DEFAULT NULL COMMENT '开始泊位ID',
  `end_berth_id` bigint DEFAULT NULL COMMENT '结束泊位ID',
  `billing_method` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '计费方式',
  `charge_code` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '收费编码(收费项目编号)',
  `charge_type` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '收费类型',
  `pilotage_start_time` datetime DEFAULT NULL COMMENT '开始引航时间',
  `pilotage_end_time` datetime DEFAULT NULL COMMENT '结束引航时间',
  `route_type` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '航线类型',
  `standard_rate2` decimal(10,2) DEFAULT NULL COMMENT '标准费率二',
  `standard_rate3` decimal(10,2) DEFAULT NULL COMMENT '标准费率三',
  `actual_standard_rate2` decimal(10,2) DEFAULT NULL COMMENT '实际标准费率二',
  `actual_standard_rate3` decimal(10,2) DEFAULT NULL COMMENT '实际标准费率三',
  `actual_billing_rate2` decimal(10,2) DEFAULT NULL COMMENT '实际计费费率2',
  `actual_billing_rate3` decimal(10,2) DEFAULT NULL COMMENT '实际计费费率3',
  `cancellation_notes` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '作废备注',
  `free_charge_flag` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '免收标记',
  `rounding_method` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '四舍五入',
  `policy_discount_reference` decimal(5,4) DEFAULT NULL COMMENT '参考政策折扣',
  `tax_invoicing_flag` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '税务开票标记',
  `tax_invoicing_time` datetime DEFAULT NULL COMMENT '税务开票时间',
  `taxpayer_full_name` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '纳税人全称',
  `taxpayer_id` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '纳税人标识号',
  `invoice_code` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '发票代码',
  `invoice_number` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '发票号码',
  `buyer_bank` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '购方开户银行',
  `total_amount` decimal(15,2) DEFAULT NULL COMMENT '总金额',
  `audit_status` enum('PENDING','APPROVED','REJECTED','REBILLING') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT 'PENDING' COMMENT '审核状态',
  `payment_status` enum('UNPAID','PARTIAL','FULLY_PAID') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT 'UNPAID' COMMENT '付款状态',
  `transfer_status` enum('PENDING','PROCESSING','COMPLETED','FAILED','REVOKED') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT 'PENDING' COMMENT '移交状态',
  `due_date` date DEFAULT NULL COMMENT '到期日',
  `discount_amount` decimal(10,2) DEFAULT NULL COMMENT '折扣金额',
  `late_fee` decimal(10,2) DEFAULT NULL COMMENT '滞纳金',
  `actual_received_amount` decimal(15,2) DEFAULT NULL COMMENT '实收金额',
  `receipt_date` date DEFAULT NULL COMMENT '收款日期',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `transfer_target` varchar(100) DEFAULT NULL COMMENT '移交目标系统（如：省港航稽征系统）',
  `transfer_type` enum('MANUAL','AUTO','RETRY') DEFAULT 'MANUAL' COMMENT '移交类型',
  `transfer_batch_no` varchar(50) DEFAULT NULL COMMENT '移交批次号',
  `transfer_time` datetime DEFAULT NULL COMMENT '移交时间',
  `transfer_operator_id` bigint DEFAULT NULL COMMENT '移交操作人ID',
  `transfer_notes` text COMMENT '移交备注',
  `external_ref_no` varchar(100) DEFAULT NULL COMMENT '外部系统参考号',
  `external_response_code` varchar(50) DEFAULT NULL COMMENT '外部系统响应代码',
  `external_response_msg` text COMMENT '外部系统响应消息',
  `last_transfer_attempt` datetime DEFAULT NULL COMMENT '最后移交尝试时间',
  `transfer_attempt_count` int DEFAULT '0' COMMENT '移交尝试次数',
  `next_retry_time` datetime DEFAULT NULL COMMENT '下次重试时间（用于自动重试）',
  `electronic_invoice_status` enum('NOT_GENERATED','GENERATING','GENERATED','SENT','RED','VOIDED') DEFAULT 'NOT_GENERATED' COMMENT '电子发票状态',
  `electronic_generated_at` datetime DEFAULT NULL COMMENT '电子发票生成时间',
  `electronic_generated_by` bigint DEFAULT NULL COMMENT '电子发票生成人ID',
  `electronic_sent_at` datetime DEFAULT NULL COMMENT '电子发票发送时间',
  `electronic_sent_by` bigint DEFAULT NULL COMMENT '电子发票发送人ID',
  `electronic_sent_to` varchar(500) DEFAULT NULL COMMENT '发送至（邮箱/手机号）',
