  `imo_number` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT 'IMO编号',
  `operation_range` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '作业范围',
  `engine_model` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '主机型号',
  `engine_power` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '主机功率',
  `rpm_thrust_forward` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT 'RPM\\拖力（正拖）',
  `rpm_thrust_reverse` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT 'RPM\\拖力（倒拖）',
  `towing_force` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '托力',
