  `current_location` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '当前位置',
  `max_speed` decimal(6,2) DEFAULT NULL COMMENT '最大航速',
  `passenger_capacity` int DEFAULT NULL COMMENT '乘员定额',
  `last_maintenance_date` date DEFAULT NULL COMMENT '最近维护日期',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `vessel_call_sign` (`vessel_call_sign`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='引航艇基本信息表';
