  `route_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '航线代码',
  `route_name` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '航线名称',
  `inbound_voyage` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '进口航次',
  `outbound_voyage` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '出口航次',
  `berthing_assistance_flag` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '助泊标记',
  `berthing_assistance_charge` decimal(10,2) DEFAULT NULL COMMENT '助泊(护航)计费',
  `withdrawal_flag` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '撤回标记',
  `pilotage_type` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '引航类型',
  `forward_draft` decimal(5,2) DEFAULT NULL COMMENT '前吃水',
  `aft_draft` decimal(5,2) DEFAULT NULL COMMENT '后吃水',
  `horsepower` decimal(10,2) DEFAULT NULL COMMENT '马力',
  `detention_flag` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '滞留标记',
  `detention_hours` decimal(6,2) DEFAULT NULL COMMENT '滞留小时数',
  `detention_persons` int DEFAULT NULL COMMENT '滞留人数',
  `pilotage_start_time` datetime DEFAULT NULL COMMENT '开始引航时间',
  `pilotage_end_time` datetime DEFAULT NULL COMMENT '结束引航时间',
  `total_passengers` int DEFAULT '0' COMMENT '旅客总数',
  `total_crew` int DEFAULT '0' COMMENT '船员总数',
  `status_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '状态编号',
  `status_name` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '状态名称',
  `boarding_time` datetime DEFAULT NULL COMMENT '登船时间',
  `leaving_time` datetime DEFAULT NULL COMMENT '离船时间',
  `notes` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '备注',
  `submit_status` enum('UNSUBMITTED','SUBMITTED','CONFIRMED') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT 'UNSUBMITTED' COMMENT '提交状态',
  `submitted_at` datetime DEFAULT NULL COMMENT '提交时间',
  `confirmed_by` bigint DEFAULT NULL COMMENT '确认人ID',
  `confirmed_at` datetime DEFAULT NULL COMMENT '确认时间',
  `billing_status` enum('UNBILLED','BILLED','BILLING_EXCEPTION','REBILLING') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT 'UNBILLED' COMMENT '计费状态',
  `special_situation_description` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '特殊情况说明',
  `pilot_sign_time` datetime DEFAULT NULL COMMENT '引航员签字时间',
  `agent_confirm_time` datetime DEFAULT NULL COMMENT '代理确认时间',
  `created_by` bigint DEFAULT NULL COMMENT '创建用户ID',
  `updated_by` bigint DEFAULT NULL COMMENT '更新用户ID',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `certificate_code` (`certificate_code`) USING BTREE,
  KEY `vessel_id` (`vessel_id`) USING BTREE,
  KEY `voyage_id` (`voyage_id`) USING BTREE,
  KEY `inbound_agent_id` (`inbound_agent_id`) USING BTREE,
  KEY `outbound_agent_id` (`outbound_agent_id`) USING BTREE,
  KEY `confirmed_by` (`confirmed_by`) USING BTREE,
  KEY `created_by` (`created_by`) USING BTREE,
  KEY `updated_by` (`updated_by`) USING BTREE,
  KEY `idx_start_location` (`start_location_type`,`start_location_id`) USING BTREE,
  KEY `idx_end_location` (`end_location_type`,`end_location_id`) USING BTREE,
  KEY `idx_start_location_name` (`start_location_name`) USING BTREE,
  KEY `idx_end_location_name` (`end_location_name`) USING BTREE,
  CONSTRAINT `pilotage_certificates_ibfk_1` FOREIGN KEY (`vessel_id`) REFERENCES `vessels` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `pilotage_certificates_ibfk_2` FOREIGN KEY (`voyage_id`) REFERENCES `voyages` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `pilotage_certificates_ibfk_3` FOREIGN KEY (`inbound_agent_id`) REFERENCES `agents` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `pilotage_certificates_ibfk_4` FOREIGN KEY (`outbound_agent_id`) REFERENCES `agents` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `pilotage_certificates_ibfk_7` FOREIGN KEY (`confirmed_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `pilotage_certificates_ibfk_8` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `pilotage_certificates_ibfk_9` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='引航签证单表';
