--
-- Table structure for table `pilotage_plans`
--

DROP TABLE IF EXISTS `pilotage_plans`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pilotage_plans` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `assigned_vehicle_id` bigint NOT NULL COMMENT '执行任务车辆ID',
  `voyage_id` bigint NOT NULL COMMENT '航次ID',
  `vessel_id` bigint NOT NULL COMMENT '船舶ID',
  `assigned_pilot_id` bigint DEFAULT NULL COMMENT '执行任务引航员ID',
  `assigned_driver_id` bigint DEFAULT NULL COMMENT '执行任务车辆驾驶员ID',
  `start_location_id` bigint DEFAULT NULL COMMENT '起始位置ID',
  `end_location_id` bigint DEFAULT NULL COMMENT '结束位置ID',
  `plan_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '引航计划编号',
  `plan_start_time` datetime NOT NULL COMMENT '引航计划开始时间',
  `plan_end_time` datetime DEFAULT NULL COMMENT '引航计划结束时间',
  `start_location_name` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '起始位置名称',
  `start_location_type` enum('ANCHORAGE','BERTH','WHARF','PORT') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '起始位置类型',
  `end_location_name` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '结束位置名称',
  `end_location_type` enum('ANCHORAGE','BERTH','WHARF','PORT') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '结束位置类型',
  `boarding_time` datetime DEFAULT NULL COMMENT '登轮时间',
  `leaving_time` datetime DEFAULT NULL COMMENT '离轮时间',
  `actual_start_time` datetime DEFAULT NULL COMMENT '引航实际开始时间',
  `actual_end_time` datetime DEFAULT NULL COMMENT '引航实际结束时间',
  `operation_type_flag` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '引航作业类型标志',
  `priority` enum('LOW','MEDIUM','HIGH','URGENT') DEFAULT 'MEDIUM',
  `vessel_schedule_status` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '船期状态标识',
  `berthing_plan_status` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '靠离泊计划状态标识',
  `pilotage_plan_status` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '引航计划状态标识',
  `table_category_flag` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '此表类别标识',
  `plan_status` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT 'PLANNING' COMMENT '计划状态\r\nPLANNING   → 计划中\r\nPLANNED    → 已计划\nPUBLISHED  → 已发布\r\nCONFIRMED  → 已确认\nONGOING    → 进行中\nCOMPLETED  → 已完成\r\nCERTIFICATED → 已签证\r\nBILLED       → 已计费\r\nPAID         → 已付款\r\nCANCELLED  → 已取消',
  `cancel_reason` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '取消原因',
  `replan_required_reason` varchar(255) DEFAULT NULL COMMENT '待重排原因（资源取消/系统原因）',
  `replan_required_resource_type` varchar(20) DEFAULT NULL COMMENT '触发待重排的资源类型',
  `replan_required_resource_id` bigint DEFAULT NULL COMMENT '触发待重排的资源ID',
  `replan_required_at` datetime DEFAULT NULL COMMENT '触发待重排时间',
  `created_by` bigint DEFAULT NULL COMMENT '创建人ID',
  `published_at` datetime DEFAULT NULL COMMENT '发布时间',
  `actual_completion_time` datetime DEFAULT NULL COMMENT '实际完成时间',
  `delay_reason` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '延误原因',
  `weather_impact` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '天气影响说明',
  `notes` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '备注',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `plan_code` (`plan_code`) USING BTREE,
  KEY `assigned_pilot_id` (`assigned_pilot_id`) USING BTREE,
  KEY `assigned_driver_id` (`assigned_driver_id`) USING BTREE,
  KEY `created_by` (`created_by`) USING BTREE,
  KEY `idx_vessel_id` (`vessel_id`) USING BTREE,
  KEY `idx_voyage_id` (`voyage_id`) USING BTREE,
  KEY `idx_vehicle_id` (`assigned_vehicle_id`) USING BTREE,
  KEY `idx_pilotage_plans_replan_required_at` (`replan_required_at`),
  CONSTRAINT `pilotage_plans_ibfk_1` FOREIGN KEY (`assigned_pilot_id`) REFERENCES `pilots` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `pilotage_plans_ibfk_2` FOREIGN KEY (`assigned_driver_id`) REFERENCES `drivers` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `pilotage_plans_ibfk_3` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='引航计划表';
/*!40101 SET character_set_client = @saved_cs_client */;

