--
-- Table structure for table `pilotage_requests`
--

DROP TABLE IF EXISTS `pilotage_requests`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pilotage_requests` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `request_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '申请表编号',
  `vessel_id` bigint NOT NULL COMMENT '船舶ID',
  `voyage_id` bigint DEFAULT NULL COMMENT '航次ID',
  `expected_berth_id` bigint DEFAULT NULL COMMENT '预计作业泊位ID',
  `reviewer_id` bigint DEFAULT NULL COMMENT '审核人ID',
  `barge_number` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '驳船号',
  `inbound_draft_forward` decimal(5,2) DEFAULT NULL COMMENT '进口吃水前',
  `inbound_draft_aft` decimal(5,2) DEFAULT NULL COMMENT '进口吃水后',
  `total_passengers` int DEFAULT '0' COMMENT '旅客总数',
  `total_crew` int DEFAULT '0' COMMENT '船员总数',
  `inbound_cargo_name` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '（进）载货名称',
  `inbound_cargo_total_weight` decimal(12,2) DEFAULT NULL COMMENT '（进）载货总吨数',
  `inbound_general_cargo_details` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '（进）普通货物名称吨数',
  `inbound_dangerous_cargo_details` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '（进）危险货物名称吨数',
  `outbound_cargo_name` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '（出）载货名称',
  `outbound_cargo_total_weight` decimal(12,2) DEFAULT NULL COMMENT '（出）载货总吨数',
  `outbound_general_cargo_details` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '（出）普通货物名称吨数',
  `outbound_dangerous_cargo_details` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '（出）危险货物名称吨数',
  `request_notes` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '申请表备注',
  `applicant` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '填报人',
  `application_date` date DEFAULT NULL COMMENT '填报日期',
  `request_source` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '申请表信息来源',
  `visa_processing_result` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '对应签证单处理结果',
  `request_status` enum('PENDING','APPROVED','REJECTED','PLANNED','IN_PROGRESS','COMPLETED','CANCELLED') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT 'PENDING' COMMENT '申请状态PENDING     待审核\nAPPROVED    已批准\nREJECTED    已驳回\nPLANNED     已排计划\nIN_PROGRESS 进行中\nCOMPLETED   已完成\nCANCELLED   已取消',
  `reviewed_at` datetime DEFAULT NULL COMMENT '审核时间',
  `reject_reason` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '驳回原因',
  `priority` enum('LOW','MEDIUM','HIGH','URGENT') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT 'MEDIUM' COMMENT '优先级',
  `special_requirements` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '特殊要求',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `request_code` (`request_code`) USING BTREE,
  KEY `vessel_id` (`vessel_id`) USING BTREE,
  KEY `voyage_id` (`voyage_id`) USING BTREE,
  KEY `expected_berth_id` (`expected_berth_id`) USING BTREE,
  KEY `reviewer_id` (`reviewer_id`) USING BTREE,
  CONSTRAINT `pilotage_requests_ibfk_1` FOREIGN KEY (`vessel_id`) REFERENCES `vessels` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `pilotage_requests_ibfk_2` FOREIGN KEY (`voyage_id`) REFERENCES `voyages` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `pilotage_requests_ibfk_3` FOREIGN KEY (`expected_berth_id`) REFERENCES `berths` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `pilotage_requests_ibfk_4` FOREIGN KEY (`reviewer_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='引航申请表';
/*!40101 SET character_set_client = @saved_cs_client */;

