--
-- Table structure for table `pilotage_routes`
--

DROP TABLE IF EXISTS `pilotage_routes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pilotage_routes` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `route_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '区间编号',
  `route_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '区间类型',
  `route_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '区间名称',
  `route_notes` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '区间备注',
  `distance_nautical` decimal(8,2) DEFAULT NULL COMMENT '距离_海里',
  `default_duration` int DEFAULT NULL COMMENT '默认航行时间（分钟）',
  `status` enum('ENABLED','DISABLED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'ENABLED' COMMENT '状态',
  `danger_level` enum('LOW','MEDIUM','HIGH') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'LOW' COMMENT '危险等级',
  `start_location_type` enum('ANCHORAGE','BERTH','OTHER') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'OTHER' COMMENT '起始位置类型',
  `start_location_id` bigint DEFAULT NULL COMMENT '起始位置ID',
  `start_location_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '起始位置名称（显示用）',
  `end_location_type` enum('ANCHORAGE','BERTH','OTHER') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'OTHER' COMMENT '结束位置类型',
  `end_location_id` bigint DEFAULT NULL COMMENT '结束位置ID',
  `end_location_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '结束位置名称（显示用）',
  `pilotage_direction` enum('IMPORT','EXPORT','SHIFTING','OTHER') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '引航方向',
  `applicable_vessel_min_net_ton` decimal(12,2) DEFAULT NULL COMMENT '适用船舶最小净吨',
  `applicable_vessel_max_net_ton` decimal(12,2) DEFAULT NULL COMMENT '适用船舶最大净吨',
  `daylight_only` tinyint(1) DEFAULT '0' COMMENT '仅限白天',
  `tide_dependent` tinyint(1) DEFAULT '0' COMMENT '依赖潮汐',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
