  KEY `idx_distance` (`distance_nautical`),
  KEY `idx_created_updated` (`created_at`,`updated_at`)
) ENGINE=InnoDB AUTO_INCREMENT=30 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='引航区间信息表';
