DROP TABLE IF EXISTS `pilots`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pilots` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `pilot_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '引航员代码',
  `pilot_name` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '引航员名称',
  `pilot_level` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '引航员级别',
  `career_start_date` date DEFAULT NULL COMMENT '从事引航年月日',
  `other_experience` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '其他海上资历',
  `health_status` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '健康状况',
  `accident_record` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '事故记录',
  `total_cargo_tonnage` decimal(15,2) DEFAULT '0.00' COMMENT '主引已经引航的货物总吨数',
  `total_operations` int DEFAULT '0' COMMENT '主引已引航的次数',
  `phone` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '联系电话',
  `sim_card` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '手机SIM卡号',
  `data_sim_card` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '网卡SIM卡号',
  `wireless_ip` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '无线网卡IP',
  `short_number` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '手机短号',
  `email` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT 'E-mail',
  `on_duty_status` enum('ON_DUTY','RESTING','LEAVE','ASSIGNED','OPERATING') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT 'ON_DUTY' COMMENT '状态：ON_DUTY-在岗, RESTING-休息, LEAVE-请假, ASSIGNED-已被分配计划, OPERATING-执行任务中',
  `emergency_contact` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '紧急联系人',
  `emergency_phone` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '紧急联系电话',
  `certificate_no` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '资质证书编号',
  `certificate_expiry` date DEFAULT NULL COMMENT '资质有效期',
  `user_id` bigint NOT NULL COMMENT '关联用户ID',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `pilot_code` (`pilot_code`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE,
  CONSTRAINT `pilots_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='引航员基本信息表';
/*!40101 SET character_set_client = @saved_cs_client */;

