DROP TABLE IF EXISTS `rate_rule_types`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `rate_rule_types` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `rule_type_code` varchar(50) NOT NULL COMMENT '规则类型编码',
  `rule_type_name` varchar(100) NOT NULL COMMENT '规则类型名称',
  `calculation_method` enum('PER_NET_TON','PER_NAUTICAL_MILE','PER_HOUR','FIXED','PERCENTAGE') NOT NULL DEFAULT 'PER_NET_TON' COMMENT '计算方式',
  `charge_item_id` bigint DEFAULT NULL COMMENT '关联的收费项目ID（用于计费明细）',
  `is_system` tinyint(1) DEFAULT '0' COMMENT '是否系统内置',
  `sort_order` int DEFAULT '0' COMMENT '排序',
  `description` text COMMENT '描述',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_rule_type_code` (`rule_type_code`),
  KEY `fk_charge_item` (`charge_item_id`),
  CONSTRAINT `fk_rate_rule_types_charge_item` FOREIGN KEY (`charge_item_id`) REFERENCES `charge_items` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb3 COMMENT='费率规则类型表';
/*!40101 SET character_set_client = @saved_cs_client */;

