DROP TABLE IF EXISTS `rate_rules`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `rate_rules` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `standard_rate_id` bigint NOT NULL COMMENT '关联原standard_rates表的ID',
  `rule_type_id` bigint NOT NULL COMMENT '费率规则类型ID',
  `rate_value` decimal(15,4) NOT NULL COMMENT '费率值',
  `applicable_vessel_min_net_ton` decimal(12,2) DEFAULT NULL COMMENT '适用船舶最小净吨（如果为空，则继承原表的）',
  `applicable_vessel_max_net_ton` decimal(12,2) DEFAULT NULL COMMENT '适用船舶最大净吨（如果为空，则继承原表的）',
  `notes` text COMMENT '备注',
  `is_active` tinyint(1) DEFAULT '1' COMMENT '是否启用',
  `version` int DEFAULT '1' COMMENT '版本号',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_standard_rate_rule_type` (`standard_rate_id`,`rule_type_id`),
  KEY `idx_standard_rate` (`standard_rate_id`),
  KEY `idx_rule_type` (`rule_type_id`),
  KEY `idx_active` (`is_active`),
  CONSTRAINT `fk_rate_rules_rule_type` FOREIGN KEY (`rule_type_id`) REFERENCES `rate_rule_types` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_rate_rules_standard_rate` FOREIGN KEY (`standard_rate_id`) REFERENCES `standard_rates` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=96 DEFAULT CHARSET=utf8mb3 COMMENT='费率规则表';
