DROP TABLE IF EXISTS `resource_online_status`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `resource_online_status` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `resource_type` varchar(50) NOT NULL COMMENT '资源类型：PILOT/DRIVER/TUGBOAT/VEHICLE/PILOT_BOAT',
  `resource_id` bigint NOT NULL COMMENT '资源ID',
  `is_online` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否在线：0否 1是',
  `updated_by` bigint DEFAULT NULL COMMENT '操作人',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_type_id` (`resource_type`,`resource_id`),
  KEY `idx_type_online` (`resource_type`,`is_online`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='资源在线状态表';
