--
-- Table structure for table `standard_rates`
--

DROP TABLE IF EXISTS `standard_rates`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `standard_rates` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `rate_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '标准费率编号',
  `category_id` bigint DEFAULT NULL COMMENT '分类ID',
  `type_id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '类型编号',
  `effective_date` date NOT NULL COMMENT '生效日期',
  `expiry_date` date DEFAULT NULL COMMENT '失效日期',
  `route_id` bigint DEFAULT NULL COMMENT '区间ID',
  `nautical_miles` decimal(8,2) DEFAULT NULL COMMENT '海里数',
  `notes` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '备注',
  `rate_status` enum('VALID','INVALID') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT 'VALID' COMMENT '状态',
  `currency_unit` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT 'CNY' COMMENT '货币单位',
  `created_by` bigint DEFAULT NULL COMMENT '创建用户ID',
  `updated_by` bigint DEFAULT NULL COMMENT '更新用户ID',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `applicable_vessel_min_net_ton` decimal(10,2) DEFAULT NULL COMMENT '适用船舶最小净吨',
  `applicable_vessel_max_net_ton` decimal(10,2) DEFAULT NULL COMMENT '适用船舶最大净吨',
  `rule_count` int DEFAULT '0' COMMENT '关联的费率规则数量',
  `condition_count` int DEFAULT '0' COMMENT '关联的条件数量',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `rate_code` (`rate_code`) USING BTREE,
  KEY `category_id` (`category_id`) USING BTREE,
  KEY `route_id` (`route_id`) USING BTREE,
  KEY `created_by` (`created_by`) USING BTREE,
  KEY `updated_by` (`updated_by`) USING BTREE,
  CONSTRAINT `standard_rates_ibfk_1` FOREIGN KEY (`category_id`) REFERENCES `charge_categories` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `standard_rates_ibfk_2` FOREIGN KEY (`route_id`) REFERENCES `pilotage_routes` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `standard_rates_ibfk_3` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `standard_rates_ibfk_4` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=65 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='标准费率信息表';
/*!40101 SET character_set_client = @saved_cs_client */;

