DROP TABLE IF EXISTS `tax_item_details`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tax_item_details` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tax_record_id` bigint NOT NULL COMMENT '税额记录ID',
  `tax_item_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '税种编码（如：VAT-增值税，CT-城建税）',
  `tax_item_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '税种名称',
  `tax_type` enum('MAIN','ADDITIONAL','OTHER') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'MAIN' COMMENT '税种类型：主税、附加税、其他',
  `tax_rate` decimal(8,6) NOT NULL COMMENT '税率（如：0.09表示9%）',
  `taxable_base` decimal(15,2) NOT NULL COMMENT '计税基数',
  `tax_amount` decimal(15,2) NOT NULL COMMENT '税额',
  `tax_policy_reference` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '税收政策依据',
  `is_preferential` tinyint(1) DEFAULT '0' COMMENT '是否享受优惠',
  `preferential_rate` decimal(8,6) DEFAULT NULL COMMENT '优惠税率',
  `preferential_amount` decimal(15,2) DEFAULT NULL COMMENT '优惠减免金额',
  `preferential_policy` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '优惠政策依据',
  `is_adjusted` tinyint(1) DEFAULT '0' COMMENT '是否经过调整',
  `adjustment_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '调整原因',
  `previous_tax_amount` decimal(15,2) DEFAULT NULL COMMENT '调整前税额',
  `sort_order` int DEFAULT '0' COMMENT '排序号',
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '备注',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
