DROP TABLE IF EXISTS `tax_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tax_records` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tax_record_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '税额记录编号（规则：TAX-YYYYMMDD-序号）',
  `voucher_id` bigint NOT NULL COMMENT '关联的计费凭证ID',
  `billing_voucher_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '计费凭证编号（冗余，便于查询）',
  `voyage_id` bigint DEFAULT NULL COMMENT '关联航次ID',
  `vessel_id` bigint DEFAULT NULL COMMENT '关联船舶ID',
  `agent_id` bigint DEFAULT NULL COMMENT '代理公司ID',
  `taxpayer_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '纳税人识别号',
  `taxpayer_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '纳税人名称',
  `taxpayer_address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '纳税人地址',
  `taxpayer_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '纳税人电话',
  `taxpayer_bank` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '纳税人开户银行',
  `taxpayer_bank_account` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '纳税人银行账号',
  `taxable_amount` decimal(15,2) DEFAULT NULL COMMENT '应税金额（通常是计费凭证总金额）',
  `total_tax_amount` decimal(15,2) DEFAULT NULL COMMENT '税额合计',
  `tax_period` date DEFAULT NULL COMMENT '所属期（格式：YYYY-MM-01）',
  `tax_calculation_time` datetime DEFAULT NULL COMMENT '计算时间',
  `tax_policy_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '税收政策编码',
  `tax_policy_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '税收政策名称',
  `is_tax_exempt` tinyint(1) DEFAULT '0' COMMENT '是否免税',
  `tax_exempt_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '免税原因',
  `tax_exempt_approval_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '免税批文号',
  `tax_status` enum('CALCULATED','REVIEW_PENDING','REVIEWED','APPROVED','REJECTED','TRANSFER_PENDING','TRANSFERRING','TRANSFERRED','REVOKED','ADJUSTED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'CALCULATED' COMMENT '税额状态',
  `transfer_target` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '移交目标系统（如：电子税务局）',
  `transfer_time` datetime DEFAULT NULL COMMENT '移交时间',
  `external_tax_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '外部系统税票号',
  `external_declaration_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '外部系统申报流水号',
  `transfer_operator_id` bigint DEFAULT NULL COMMENT '移交操作人ID',
  `transfer_notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '移交备注',
  `reviewer_id` bigint DEFAULT NULL COMMENT '审核人ID',
  `review_time` datetime DEFAULT NULL COMMENT '审核时间',
  `review_notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '审核意见',
  `approver_id` bigint DEFAULT NULL COMMENT '批准人ID',
  `approve_time` datetime DEFAULT NULL COMMENT '批准时间',
  `calculation_method` enum('AUTO','MANUAL','ADJUSTED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'AUTO' COMMENT '计算方式',
  `data_source` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '数据来源（如：自动计算、手工录入）',
  `version` int DEFAULT '1' COMMENT '版本号（用于乐观锁）',
  `is_active` tinyint(1) DEFAULT '1' COMMENT '是否有效',
  `created_by` bigint DEFAULT NULL COMMENT '创建人ID',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人ID',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tax_record_code` (`tax_record_code`),
  KEY `idx_voucher_id` (`voucher_id`),
  KEY `idx_agent_id` (`agent_id`),
  KEY `idx_tax_status` (`tax_status`),
  KEY `idx_tax_period` (`tax_period`),
  KEY `idx_taxpayer_id` (`taxpayer_id`),
  KEY `idx_transfer_time` (`transfer_time`),
  KEY `idx_created_at` (`created_at`),
  KEY `idx_billing_voucher_code` (`billing_voucher_code`),
  KEY `idx_external_tax_no` (`external_tax_no`),
  KEY `idx_transfer_target` (`transfer_target`),
  KEY `fk_tax_voyage` (`voyage_id`),
  KEY `fk_tax_vessel` (`vessel_id`),
  CONSTRAINT `tax_records_ibfk_1` FOREIGN KEY (`voucher_id`) REFERENCES `billing_vouchers` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `tax_records_ibfk_2` FOREIGN KEY (`voyage_id`) REFERENCES `voyages` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `tax_records_ibfk_3` FOREIGN KEY (`vessel_id`) REFERENCES `vessels` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='税额主记录表';
