DROP TABLE IF EXISTS `tide_info`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tide_info` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tide_date` datetime NOT NULL COMMENT '日期时间',
  `region` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '所属区域',
  `high_tide_time1` time DEFAULT NULL COMMENT '高潮时间1',
  `high_tide_height1` decimal(5,2) DEFAULT NULL COMMENT '高潮潮高1',
  `high_tide_time2` time DEFAULT NULL COMMENT '高潮时间2',
  `high_tide_height2` decimal(5,2) DEFAULT NULL COMMENT '高潮潮高2',
  `low_tide_time1` time DEFAULT NULL COMMENT '低潮时间1',
  `low_tide_height1` decimal(5,2) DEFAULT NULL COMMENT '低潮潮高1',
  `low_tide_time2` time DEFAULT NULL COMMENT '低潮时间2',
  `low_tide_height2` decimal(5,2) DEFAULT NULL COMMENT '低潮潮高2',
  `tide_type` enum('SPRING','NEAP','MEDIUM') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '潮汐类型',
  `data_source` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '数据来源',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_tide_date_region` (`tide_date`,`region`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1635 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='潮汐信息表';
