/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vessels` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `vessel_call_sign` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '船舶呼号',
  `imo_number` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT 'IMO编号',
  `mmsi_number` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT 'MMSI编号',
  `vessel_type` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '船舶类型',
  `nationality` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '国籍',
  `owner_zh` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '船舶所有人（中文）',
  `owner_en` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '船舶所有人（英文）',
  `route_scope` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '航线范围',
  `route_type` enum('INTERNATIONAL','DOMESTIC') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT 'DOMESTIC' COMMENT '航线种类',
  `name_zh` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '中文船名',
  `name_en` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '英文船名',
  `vessel_length` decimal(8,2) DEFAULT NULL COMMENT '船舶长度',
  `vessel_width` decimal(8,2) DEFAULT NULL COMMENT '船舶宽度',
  `full_load_draft` decimal(6,2) DEFAULT NULL COMMENT '满载吃水',
  `depth` decimal(6,2) DEFAULT NULL COMMENT '型深',
  `max_height` decimal(6,2) DEFAULT NULL COMMENT '最大高度',
  `air_draft` decimal(6,2) DEFAULT NULL COMMENT '水面上高度',
  `speed` decimal(6,2) DEFAULT NULL COMMENT '船速',
  `gross_tonnage` decimal(12,2) DEFAULT NULL COMMENT '总吨',
  `net_tonnage` decimal(12,2) DEFAULT NULL COMMENT '净吨',
  `deadweight` decimal(12,2) DEFAULT NULL COMMENT '载重吨',
  `main_engine_type` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '主机种类',
  `main_engine_power` decimal(10,2) DEFAULT NULL COMMENT '主机功率(kW)',
  `bow_thruster_power` decimal(10,2) DEFAULT NULL COMMENT '侧推功率(kW)',
  `ais_pilot_interface` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT 'AIS引航接口',
  `vessel_color` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '船舶颜色',
  `funnel_color` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '烟囱颜色',
  `funnel_mark` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '烟囱标志',
  `build_date` date DEFAULT NULL COMMENT '建造年月',
  `blacklist_record` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '黑名单记录',
  `bad_status_record` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '不良状态记录',
  `other_abnormal_record` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '其他非正常状态记录',
  `port_of_registry` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '船籍港',
  `classification_society` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '船级社',
  `management_company` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '管理公司',
  `insurance_company` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '保险公司',
  `pni_club` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '保赔协会',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `vessel_call_sign` (`vessel_call_sign`) USING BTREE,
  UNIQUE KEY `imo_number` (`imo_number`) USING BTREE,
  UNIQUE KEY `mmsi_number` (`mmsi_number`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='船舶基本资料表';
