--
-- Table structure for table `voyages`
--

DROP TABLE IF EXISTS `voyages`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `voyages` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '航次ID',
  `vessel_id` bigint NOT NULL COMMENT '船舶ID',
  `agent_id` bigint DEFAULT NULL COMMENT '代理公司ID',
  `actual_start_id` bigint DEFAULT NULL COMMENT '实际开始位置ID',
  `planned_start_id` bigint DEFAULT NULL COMMENT '计划开始位置ID',
  `port_of_destination_id` bigint DEFAULT NULL COMMENT '目的港ID',
  `port_of_departure_id` bigint DEFAULT NULL COMMENT '出发港ID',
  `planned_end_id` bigint DEFAULT NULL COMMENT '计划结束位置ID',
  `actual_end_id` bigint DEFAULT NULL COMMENT '实际结束位置ID',
  `pilotage_requests_id` bigint DEFAULT NULL COMMENT '引航申请id',
  `voyage_number` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '航次编号',
  `voyage_type` enum('IMPORT','EXPORT','TRANSIT') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '航次类型',
  `start_location_type` enum('BERTH','ANCHORAGE') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '开始位置类型 (泊位/锚地)',
  `end_location_type` enum('BERTH','ANCHORAGE') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '结束位置类型 (泊位/锚地)',
  `previous_port` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '上一港',
  `next_port` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '下一港',
  `eta` datetime DEFAULT NULL COMMENT '预计到港时间',
  `eta_anchorage` datetime DEFAULT NULL COMMENT '预抵锚地时间',
  `ata` datetime DEFAULT NULL COMMENT '实际到港时间',
  `etd` datetime DEFAULT NULL COMMENT '预计离港时间',
  `atd` datetime DEFAULT NULL COMMENT '实际离港时间',
  `cargo_name` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '装货名称',
  `cargo_type` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '货物类型',
  `cargo_quantity` decimal(12,2) DEFAULT NULL COMMENT '货物数量',
  `cargo_unit` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '货物单位',
  `draft_forward` decimal(6,2) DEFAULT NULL COMMENT '前吃水',
  `draft_aft` decimal(6,2) DEFAULT NULL COMMENT '后吃水',
  `total_passengers` int DEFAULT '0' COMMENT '旅客总数',
  `total_crew` int DEFAULT '0' COMMENT '船员总数',
  `voyage_status` enum('PLANNING','ON_ROUTE','IN_PORT','COMPLETED','CANCELLED') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT 'PLANNING' COMMENT '航次状态',
  `remarks` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '航次备注',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_voyage_number` (`voyage_number`) USING BTREE,
  KEY `idx_vessel_id` (`vessel_id`) USING BTREE,
  KEY `idx_eta` (`eta`) USING BTREE,
  KEY `idx_etd` (`etd`) USING BTREE,
  KEY `agent_id` (`agent_id`) USING BTREE,
  KEY `actual_berth_id` (`actual_start_id`) USING BTREE,
  KEY `port_of_departure_id` (`port_of_departure_id`) USING BTREE,
  KEY `port_of_destination_id` (`port_of_destination_id`) USING BTREE,
  KEY `actual_anchorage_id` (`actual_end_id`) USING BTREE,
  KEY `planned_end_id` (`planned_end_id`) USING BTREE,
  KEY `planned_start_id` (`planned_start_id`) USING BTREE,
  CONSTRAINT `voyages_ibfk_1` FOREIGN KEY (`vessel_id`) REFERENCES `vessels` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `voyages_ibfk_2` FOREIGN KEY (`agent_id`) REFERENCES `agents` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `voyages_ibfk_4` FOREIGN KEY (`actual_start_id`) REFERENCES `berths` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `voyages_ibfk_5` FOREIGN KEY (`port_of_departure_id`) REFERENCES `ports` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `voyages_ibfk_6` FOREIGN KEY (`port_of_destination_id`) REFERENCES `ports` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `voyages_ibfk_actual_anchorage` FOREIGN KEY (`actual_end_id`) REFERENCES `anchorages` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='船舶航次信息表。位置逻辑：voyage_type决定业务场景，start/end_location_type和ID共同记录具体位置。';
/*!40101 SET character_set_client = @saved_cs_client */;

