--
-- Table structure for table `weather_info`
--

DROP TABLE IF EXISTS `weather_info`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `weather_info` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `weather_date` datetime NOT NULL COMMENT '气象日期时间',
  `weather_sequence` int DEFAULT NULL COMMENT '气象次别',
  `weather_content` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '气象内容',
  `temperature` decimal(4,1) DEFAULT NULL COMMENT '温度',
  `humidity` decimal(4,1) DEFAULT NULL COMMENT '湿度',
  `wind_speed` decimal(5,2) DEFAULT NULL COMMENT '风速',
  `wind_direction` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '风向',
  `visibility` decimal(5,2) DEFAULT NULL COMMENT '能见度',
  `pressure` decimal(6,2) DEFAULT NULL COMMENT '气压',
  `weather_condition` enum('SUNNY','CLOUDY','OVERCAST','SHOWER','STORMY','HAIL','SLEET','DRIZZLE','RAINY','SNOWY','FOGGY','FROZEN_RAIN','DUST_STORM','HAZE','STORM','TYPHOON','HEAVY_RAIN','HEAVY_SNOW') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '天气状况',
  `data_source` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '数据来源',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_weather_date_sequence` (`weather_date`,`weather_sequence`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=573 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='气象信息表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `weather_info`
--

LOCK TABLES `weather_info` WRITE;
/*!40000 ALTER TABLE `weather_info` DISABLE KEYS */;
