--
-- Table structure for table `wharves`
--

DROP TABLE IF EXISTS `wharves`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wharves` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `port_area_id` bigint NOT NULL COMMENT '所属港区ID',
  `wharf_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '码头代码',
  `wharf_name_zh` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '码头中文名称',
  `wharf_name_en` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '码头英文名称',
  `wharf_length` decimal(8,2) DEFAULT NULL COMMENT '码头长度(米)',
  `wharf_depth` decimal(6,2) DEFAULT NULL COMMENT '码头水深(米)',
  `construction_date` date DEFAULT NULL COMMENT '建成日期',
  `wharf_type` enum('CONTAINER','BULK','GENERAL','OIL','PASSENGER','MULTIPURPOSE') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT 'GENERAL' COMMENT '码头类型',
  `operational_status` enum('OPERATIONAL','MAINTENANCE','CLOSED','CONSTRUCTION') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT 'OPERATIONAL' COMMENT '运营状态',
  `management_company` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '管理公司',
  `contact_phone` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '联系电话',
  `longitude` decimal(10,6) DEFAULT NULL COMMENT '中心经度',
  `latitude` decimal(10,6) DEFAULT NULL COMMENT '中心纬度',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_wharf_code` (`wharf_code`) USING BTREE,
  KEY `port_area_id` (`port_area_id`) USING BTREE,
  CONSTRAINT `wharves_ibfk_1` FOREIGN KEY (`port_area_id`) REFERENCES `port_areas` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='码头信息表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `wharves`
--

LOCK TABLES `wharves` WRITE;
/*!40000 ALTER TABLE `wharves` DISABLE KEYS */;
