--
-- Table structure for table `work_sheets`
--

DROP TABLE IF EXISTS `work_sheets`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `work_sheets` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `worksheet_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '工作表编号',
  `plan_start_time` datetime DEFAULT NULL COMMENT '引航计划开始时间',
  `plan_end_time` datetime DEFAULT NULL COMMENT '引航计划结束时间',
  `start_location` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '引航起始地点',
  `end_location` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '引航结束地点',
  `assigned_tugboats` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '执行任务拖轮',
  `assigned_pilot_boats` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '执行任务引航艇',
  `assigned_pilot_id` bigint DEFAULT NULL COMMENT '执行任务引航员ID',
  `assigned_driver_id` bigint DEFAULT NULL COMMENT '执行任务车辆驾驶员ID',
  `boarding_time` datetime DEFAULT NULL COMMENT '登轮时间',
  `leaving_time` datetime DEFAULT NULL COMMENT '离轮时间',
  `actual_start_time` datetime DEFAULT NULL COMMENT '引航实际开始时间',
  `actual_end_time` datetime DEFAULT NULL COMMENT '引航实际结束时间',
  `operation_type_flag` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '引航作业类型标志',
  `work_status` enum('NOT_STARTED','ONGOING','COMPLETED','ABNORMAL') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT 'NOT_STARTED' COMMENT '工作状态',
  `completion_quality_score` int DEFAULT NULL COMMENT '完成质量评分',
  `special_situation_record` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '特殊情况记录',
  `customer_feedback` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '客户反馈',
  `work_duration` int DEFAULT NULL COMMENT '工作时长（分钟）',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
